function validateCPF(t){const r=t.replace(/[.-\s]/g,"");if(11!==r.length)return!1;if(/^(\d)\1{10}$/.test(r))return!1;let e,n=0;for(let t=1;t<=9;t++)n+=parseInt(r.substring(t-1,t))*(11-t);if(e=10*n%11,e=10===e||11===e?0:e,e!==parseInt(r.substring(9,10)))return!1;n=0;for(let t=1;t<=10;t++)n+=parseInt(r.substring(t-1,t))*(12-t);let s=10*n%11;return s=10===s||11===s?0:s,s===parseInt(r.substring(10,11))}function validateCNPJ(t){if(14!==(t=t.replace(/[^\d]+/g,"")).length)return!1;if(/^(\d)\1{13}$/.test(t))return!1;let r=t.length-2,e=t.substring(0,r),n=t.substring(r),s=0,i=r-7;for(let t=r;t>=1;t--)s+=e.charAt(r-t)*i--,i<2&&(i=9);if((s%11<2?0:11-s%11)!==parseInt(n.charAt(0),10))return!1;r+=1,e=t.substring(0,r),s=0,i=r-7;for(let t=r;t>=1;t--)s+=e.charAt(r-t)*i--,i<2&&(i=9);return(s%11<2?0:11-s%11).toString()===n.charAt(1)}function validateDocument(t,r){return"CPF"===r?validateCPF(t):"CNPJ"===r&&validateCNPJ(t)}